from django.db import models
from django.db.models import F

class TestModel(models.Model):
    name = models.CharField(max_length=100)
    value = models.IntegerField()

    class Meta:
        app_label = 'test_app'

# Test with exact lookup
print('Testing F expression with exact lookup:')
try:
    q = TestModel.objects.filter(name=F('value'))
    print(f'  Works: {q.query}')
except Exception as e:
    print(f'  Error: {e}')

# Test with gt lookup
print('\\nTesting F expression with gt lookup:')
try:
    q = TestModel.objects.filter(value__gt=F('value'))
    print(f'  Works: {q.query}')
except Exception as e:
    print(f'  Error: {e}')
