from django.db.migrations.autodetector import MigrationAutodetector
from django.db.migrations.state import ProjectState, ModelState
from django.db.migrations.questioner import MigrationQuestioner
from django.db import models

# Test case from the test file - non-primary key field
print('Test 1: Renaming a non-primary key field with ForeignKey to_field')
print('=' * 80)

before = [
    ModelState('app', 'Foo', [
        ('id', models.AutoField(primary_key=True)),
        ('field', models.IntegerField(unique=True)),
    ]),
    ModelState('app', 'Bar', [
        ('id', models.AutoField(primary_key=True)),
        ('foo', models.ForeignKey('app.Foo', models.CASCADE, to_field='field')),
    ]),
]
after = [
    ModelState('app', 'Foo', [
        ('id', models.AutoField(primary_key=True)),
        ('renamed_field', models.IntegerField(unique=True)),
    ]),
    ModelState('app', 'Bar', [
        ('id', models.AutoField(primary_key=True)),
        ('foo', models.ForeignKey('app.Foo', models.CASCADE, to_field='renamed_field')),
    ]),
]

initial_state = ProjectState()
for model in before:
    initial_state.add_model(model)

target_state = ProjectState()
for model in after:
    target_state.add_model(model)

questioner = MigrationQuestioner({'ask_rename': True})
autodetector = MigrationAutodetector(initial_state, target_state, questioner)
changes = autodetector._detect_changes(None, None)

print('Generated operations:')
for app_label, app_changes in changes.items():
    for migration in app_changes:
        for operation in migration.operations:
            print(f'  {operation}')
            if hasattr(operation, 'field') and hasattr(operation.field, 'remote_field'):
                if hasattr(operation.field.remote_field, 'field_name'):
                    print(f'    to_field: {operation.field.remote_field.field_name}')

